{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "17β-estradiol, the closest analogue, has an absolute oral bioavailability of about 5% in humans, but this low value is driven by rapid first-pass metabolism at the C17 hydroxyl, a position that is structurally protected in the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C27"],
      "claim": "Ethinylestradiol, which shares the query's protected C17 tertiary-alcohol/D-ring motif, showed 38% oral bioavailability in women, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Estetrol, a polyhydroxylated estrogen, is reported to have high and dose-related oral bioavailability in humans, indicating that additional hydroxyl groups do not necessarily cause low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Moxestrol, a synthetic estrogen with D-ring modifications, had an absolute oral bioavailability of 35% in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F ≥ 20%) because the query is a D-ring-modified estradiol with a protected tertiary C17 alcohol and an extra ring, analogous to ethinylestradiol, estetrol, and moxestrol, which show oral bioavailability around 35-47% or higher; the low F of estradiol is largely due to C17 oxidation that is blocked in the query.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the exact query molecule; its precise structure/configuration is not fully resolved from the SMILES.",
    "Record C18 is attached to an estrone-like SMILES but reports ethinylestradiol-like bioavailability values, adding uncertainty to that evidence.",
    "Human absolute oral bioavailability data for the exact cyclopropane-fused estrane are absent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

